"""Generate a native test using the actual Palette function, not a reimplementation.

Usage: python test/generate_palette_test.py output.cpp [original-source.zip]
Compile with wled00 on the include path; repeat with ESP8266 defined to test its
integer branch. The optional original archive proves this test detects the bug.
"""
# AI: below section was generated by an AI
from pathlib import Path
import re
import sys
import zipfile


def function(source, name):
    """Extract a complete C++ function, ignoring braces in comments and strings."""
    clean = re.sub(r'//[^\n]*|/\*[\s\S]*?\*/|"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'',
                   lambda match: ' ' * len(match[0]), source)
    match = re.search(r'^(?:static )?(?:void|uint64_t|uint32_t) '+name+r'\([^\n]*\)\s*\{', clean, re.M)
    assert match, name
    start = clean.index('{', match.start())
    depth = 1
    end = start + 1
    while depth:
        depth += (clean[end] == '{') - (clean[end] == '}')
        end += 1
    return source[match.start():end]


project = Path(__file__).resolve().parents[1]
source = (project/'wled00/FX.cpp').read_text(encoding='utf-8')
template = (project/'test/palette_harness.cpp.in').read_text(encoding='utf-8')
actual = '\n\n'.join(function(source, name) for name in ('fxClock', 'fxTime', 'mode_palette'))
baseline = ''
if len(sys.argv) > 2:
    with zipfile.ZipFile(sys.argv[2]) as archive:
        name = next(n for n in archive.namelist() if n.endswith('/wled00/FX.cpp'))
        original = archive.read(name).decode('utf-8-sig')
        baseline = '#define HAS_BASELINE\n' + function(original, 'mode_palette').replace('mode_palette()', 'original_palette()')
Path(sys.argv[1]).write_text(template.replace('// @ACTUAL_FUNCTIONS@', actual).replace('// @BASELINE@', baseline), encoding='utf-8')
print('Generated test with the current Palette implementation')
